import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static int nextInt() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        int r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), k = nextInt();
        int[] freq = new int[100001];
        int most = 0;
        for (int i = 0; i < n; i++) most = Math.max(most, ++freq[nextInt()]);
        // Feasible iff k divides n and no value appears more often than the n/k groups.
        System.out.println(n % k == 0 && most <= n / k ? "Yes" : "No");
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	r := 0
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n, k := nextInt(), nextInt()
	freq := make([]int, 100001)
	most := 0
	for i := 0; i < n; i++ {
		v := nextInt()
		freq[v]++
		most = max(most, freq[v])
	}
	// Feasible iff k divides n and no value appears more often than the n/k groups.
	if n%k == 0 && most <= n/k {
		fmt.Println("Yes")
	} else {
		fmt.Println("No")
	}
}
